8	import { Button } from "@/shared/ui/button";
9	import { MiaGreetingCard } from "@/features/mia/ui/MiaGreetingCard";
10	// MiaMobileSheet removido — clique navega pra /mia
11	import { useSystemAnnouncements } from "@/features/announcements";
12	import {
13	  DropdownMenu,
14	  DropdownMenuContent,
15	  DropdownMenuItem,
