27	type FeatureCardProps = {
28	  title: string;
29	  icon: React.ElementType;
30	  onClick: () => void;
31	};
32	
33	function FeatureCard({ title, icon: Icon, onClick }: FeatureCardProps) {
34	  const slug = title.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
35	  return (
36	    <button
37	      data-mia-action={`abrir-feature-${slug}`}
38	      data-mia-feature-title={title}
39	      onClick={onClick}
40	      className="group flex flex-col items-center gap-2 p-2 transition-all duration-300 active:scale-95"
41	    >
42	      {/* Arched Card Design mimicking the store shelves */}
43	      <div
44	        className={cn(
45	          'relative flex items-center justify-center h-[80px] w-[72px]',
46	          'rounded-t-[36px] rounded-b-[12px]', // Arch shape
47	          'bg-white dark:bg-[#1A1A1A]', // Pure white background for contrast
48	          'border-[2px] border-[#C5A065] dark:border-[#C5A065]/50', // Gold border for premium highlight
49	          'shadow-[0_8px_20px_-6px_rgba(87,113,91,0.25),0_4px_8px_-2px_rgba(197,160,101,0.15)]', // Richer shadow with green and gold tones
50	          'group-hover:border-[#57715B] dark:group-hover:border-[#57715B] group-hover:shadow-[0_12px_24px_-6px_rgba(87,113,91,0.4)] transition-all duration-300',
51	        )}
52	      >
53	        {/* Inner Arch Accent (Depth) - Subtle Green Tint */}
54	        <div className="absolute inset-[3px] rounded-t-[30px] rounded-b-[9px] border border-[#57715B]/10 dark:border-white/5 bg-[#57715B]/[0.02]" />
55	
56	        {/* Bottom Gold Accent Line */}
57	        <div className="absolute bottom-3 w-8 h-1 bg-[#C5A065] rounded-full opacity-40" />
58	
59	        <Icon
60	          className="h-8 w-8 text-[#57715B] dark:text-[#8FA893] group-hover:scale-110 transition-transform duration-300 relative z-10 drop-shadow-sm"
61	          strokeWidth={1.5}
62	        />
63	      </div>
64	
65	      <span className="text-[11px] font-bold tracking-wide text-[#2D362E] dark:text-[#E6DCCF] text-center leading-tight max-w-[80px] line-clamp-2 uppercase drop-shadow-sm group-hover:text-[#57715B] transition-colors">
66	        {title}
67	      </span>
68	    </button>
69	  );
70	}
