73	export default function MobileHome() {
74	  const isMobile = useIsMobile();
75	  const navigate = useNavigate();
76	  const location = useLocation();
77	  const containerRef = useRef<HTMLDivElement | null>(null);
78	  const { theme, setTheme } = useTheme();
79	  const [serverVersion, setServerVersion] = useState<string | null>(null);
80	
81	  useEffect(() => {
82	    fetch(`/version.json?t=${Date.now()}`)
83	      .then(res => res.json())
84	      .then(data => setServerVersion(data.version))
85	      .catch(err => wideError('dashboard.mobile_home.version_fetch_error', 'Falha ao buscar versão do servidor', { attributes: { 'error.message': err instanceof Error ? err.message : String(err), 'operation.name': 'fetchServerVersion' } }));
86	  }, []);
87	
88	  const getInitialIndex = () => {
89	    const params = new URLSearchParams(location.search);
90	    const cat = (params.get('category') || '').toLowerCase();
91	    const idxByParam = categories.findIndex(
92	      (c) => c.name.toLowerCase() === cat,
93	    );
94	    if (idxByParam >= 0) return idxByParam;
95	    const estoqueIdx = categories.findIndex(
96	      (c) => c.name.toLowerCase() === 'estoque',
97	    );
98	    return estoqueIdx >= 0 ? estoqueIdx : 0;
99	  };
100	
101	  const [pageIndex, setPageIndex] = useState<number>(getInitialIndex());
102	  const { user, signOut } = useAuth();
103	  const { unreadCount: miaUnreadCount } = useSystemAnnouncements();
104	
105	  useLayoutEffect(() => {
106	    const el = containerRef.current;
107	    if (!el) return;
108	    const onScroll = () => {
109	      const w = el.clientWidth;
110	      const idx = Math.round(el.scrollLeft / w);
111	      setPageIndex(Math.max(0, Math.min(categories.length - 1, idx)));
112	    };
113	    el.addEventListener('scroll', onScroll, { passive: true });
114	    const initialIdx = getInitialIndex();
115	    const w = el.clientWidth;
116	    el.scrollTo({ left: w * initialIdx, behavior: 'auto' });
117	    setPageIndex(initialIdx);
118	    return () => el.removeEventListener('scroll', onScroll);
119	    // eslint-disable-next-line react-hooks/exhaustive-deps
120	  }, [location.search]);
121	
122	  if (!isMobile) return null;
123	
124	  return (
125	    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
126	      {/* Store Awning Stripe Effect (Top Border) */}
127	      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
128	
129	      {/* Animated Plant Background Elements - Restored Pulse */}
130	      <div
131	        className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
132	        style={{ animationDuration: '10s' }}
133	      >
134	        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
135	      </div>
136	      <div
137	        className="absolute bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
138	        style={{ animationDuration: '12s' }}
139	      >
140	        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
141	      </div>
142	
143	      {/* Soft Ambient Glows */}
144	      <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
145	      <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />
146	
147	      {/* Header Bar */}
148	      <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
149	        {/* Logo Placement */}
150	        <div className="flex items-center gap-3">
151	          <div className="relative h-12 w-auto">
152	            <img
153	              src="/logo sistema/01. Reduzida 5.png"
154	              alt="Momma"
155	              className="h-full w-auto object-contain dark:hidden drop-shadow-sm"
156	            />
157	            <img
158	              src="/logo sistema/01. Reduzida branco.png"
159	              alt="Momma"
160	              className="h-full w-auto object-contain hidden dark:block drop-shadow-sm"
161	            />
162	          </div>
163	        </div>
164	
165	        {/* Right Actions */}
166	        <div className="flex items-center gap-3">
167	          {/* Store Selector */}
168	          <StoreSelector />
169	
170	          {/* Theme Toggle */}
171	          <Button
172	            data-mia-action="toggle-tema"
173	            variant="ghost"
174	            size="icon"
175	            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
176	            className="h-10 w-10 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
177	          >
178	            <Sun className="h-5 w-5 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
179	            <Moon className="absolute h-5 w-5 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
180	          </Button>
181	
182	          {/* Profile Menu */}
183	          <DropdownMenu>
184	            <DropdownMenuTrigger asChild>
185	              <Button
186	                data-mia-action="abrir-menu-perfil"
187	                variant="ghost"
188	                className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative"
189	              >
190	                <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
191	                  <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
192	                    {(user?.user_metadata?.nome || 'U')
193	                      .slice(0, 2)
194	                      .toUpperCase()}
195	                  </AvatarFallback>
196	                </Avatar>
197	              </Button>
198	            </DropdownMenuTrigger>
199	            <DropdownMenuContent
200	              className="w-64 rounded-2xl border-[#E6DCCF] dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl"
201	              align="end"
202	              sideOffset={8}
203	            >
204	              <DropdownMenuLabel className="font-normal p-4">
205	                <div className="flex flex-col space-y-1">
206	                  <p className="text-base font-semibold leading-none text-[#57715B] dark:text-zinc-100">
207	                    {user?.user_metadata?.nome || userProfile?.nome}
208	                  </p>
209	                  <p className="text-xs text-zinc-500">{user?.email}</p>
210	                </div>
211	              </DropdownMenuLabel>
212	              <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
213	
214	              {/* Store Selector removed from here as it's now in the header */}
215	
216	              {/* Version Indicator */}
217	              <div className="px-2 py-1.5 text-[10px] text-center text-zinc-400 select-none">
218	                v{String(__APP_VERSION__)} / srv {serverVersion || '...'}
219	              </div>
220	              <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
221	              <DropdownMenuItem
222	                data-mia-action="sair"
223	                className="p-3 m-1 text-red-500 focus:text-red-600 focus:bg-red-50 dark:focus:bg-red-950/30 rounded-xl"
224	                onClick={async () => {
225	                  await signOut();
226	                  toast.success('Até logo!');
227	                }}
228	              >
229	                <LogOut className="mr-2 h-4 w-4" />
230	                Sair
231	              </DropdownMenuItem>
232	            </DropdownMenuContent>
233	          </DropdownMenu>
234	        </div>
235	      </div>
236	
237	      {/* MiaGreetingCard — aberto para todos os usuários */}
238	      <div data-mia-action="abrir-mia" className="px-6 mb-8 z-10 mt-6">
239	        <MiaGreetingCard
240	          onTap={() => navigate('/mia')}
241	          unreadAnnouncements={miaUnreadCount}
242	        />
243	      </div>
244	
245	      {/* Main Content Area - Full Screen Width */}
246	      <div className="flex-1 relative z-10 flex flex-col">
247	        {/* Category Title & Navigation */}
248	        <div className="px-8 mb-4 flex items-center justify-between">
249	          <h3 className="text-lg font-bold text-[#57715B] dark:text-white tracking-wide uppercase">
250	            {categories[pageIndex]?.name}
251	          </h3>
252	
253	          {/* Modern Pill Indicator */}
254	          <div className="flex items-center gap-1 bg-[#E6DCCF]/40 dark:bg-zinc-800/50 rounded-full px-2 py-1">
255	            {categories.map((_, i) => (
256	              <div
257	                key={i}
258	                className={cn(
259	                  'h-1.5 rounded-full transition-all duration-500 ease-spring',
260	                  i === pageIndex
261	                    ? 'w-6 bg-[#57715B]'
262	                    : 'w-1.5 bg-[#57715B]/20 dark:bg-zinc-600',
263	                )}
264	              />
265	            ))}
266	          </div>
267	        </div>
268	
269	        {/* Horizontal Scroll Container - Full Width */}
270	        <div
271	          ref={containerRef}
272	          className="flex-1 overflow-x-auto snap-x snap-mandatory flex scrollbar-hide pb-8 touch-pan-x"
273	          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
274	        >
275	          {categories.map((cat, idx) => (
276	            <div
277	              key={idx}
278	              className={cn(
279	                'min-w-full snap-center px-4 transition-all duration-500 ease-out',
280	                'snap-always',
281	                // Optimized focus effect: Removed blur, using only opacity and scale
282	                idx === pageIndex
283	                  ? 'opacity-100 scale-100'
284	                  : 'opacity-40 scale-95',
285	              )}
286	              style={{ scrollSnapStop: 'always' }}
287	            >
288	              <div className="grid grid-cols-3 sm:grid-cols-4 gap-y-8 gap-x-2 place-items-center content-start">
289	                {cat.items.map((item) => (
290	                  <FeatureCard
291	                    key={item.title}
292	                    title={item.title}
293	                    icon={item.icon}
294	                    onClick={() => navigate(item.url)}
295	                  />
296	                ))}
297	              </div>
298	            </div>
299	          ))}
300	        </div>
301	      </div>
302	
303	      {/* Mobile Footer */}
304	      <div className="pt-4 pb-[calc(1rem+env(safe-area-inset-bottom))] flex flex-col items-center justify-center gap-2 z-10 relative w-full mt-auto">
305	        <div className="flex items-center gap-2 drop-shadow-[0_1px_1px_rgba(255,255,255,0.5)] dark:drop-shadow-none">
306	          <img
307	            src="/logo sistema/01. Reduzida 5.png"
308	            alt="Momma"
309	            className="h-5 w-auto object-contain dark:hidden opacity-90"
310	          />
311	          <img
312	            src="/logo sistema/01. Reduzida branco.png"
313	            alt="Momma"
314	            className="h-5 w-auto object-contain hidden dark:block opacity-90"
315	          />
316	          <span className="text-xs font-bold text-[#4A3728] dark:text-[#E6DCCF] uppercase tracking-wider">
317	            sistema GIDAPE
318	          </span>
319	        </div>
320	      </div>
321	
322	    </div>
323	  );
324	}
