1	import { SidebarProvider } from '@/shared/ui/sidebar';
2	import { AppSidebar } from './AppSidebar';
3	import { StoreChangeNotification } from './StoreChangeNotification';
4	import { usePendingNfCaptureRedirect } from '@/features/notas-fiscais/model/usePendingNfCaptureRedirect';
5	import { useIsMobile } from '@/shared/hooks/use-mobile';
6	import { useLocation } from 'react-router-dom';
7	import { cn } from '@/shared/lib/utils';
8	import { useActivityTracker } from '@/hooks/useActivityTracker';
9	import { useMiaBehaviorTracker, useCounterfactualTracker } from '@/shared/lib/analytics';
10	
11	interface DashboardLayoutProps {
12	  children: React.ReactNode;
13	}
14	
15	/**
16	 * Inner — renderiza UI. Separado do Provider pra poder consumir o context.
17	 */
18	function DashboardLayoutInner({ children }: DashboardLayoutProps) {
19	  useActivityTracker();
20	  useMiaBehaviorTracker();
21	  useCounterfactualTracker();
22	  usePendingNfCaptureRedirect();
23	  const isMobile = useIsMobile();
24	  const location = useLocation();
25	  const isDashboard = location.pathname === '/dashboard';
26	
27	  // Pages that use p-0 (full-bleed content, no padding)
28	  const isFullBleedPage =
29	    (isMobile && isDashboard) ||
30	    location.pathname === '/dashboard' ||
31	    location.pathname.startsWith('/eventos') ||
32	    location.pathname.startsWith('/producao') ||
33	    location.pathname === '/verificacao-perdas' ||
34	    location.pathname === '/marketing' ||
35	    location.pathname === '/encomendas' ||
36	    location.pathname === '/produtos' ||
37	    location.pathname === '/produtos/analytics' ||
38	    location.pathname === '/notas-fiscais' ||
39	    location.pathname === '/financeiro' ||
40	    location.pathname === '/movimentacoes' ||
41	    location.pathname === '/pronta-entrega' ||
42	    location.pathname === '/producao-diaria' ||
43	    location.pathname === '/vendas' ||
44	    location.pathname === '/etiquetas' ||
45	    location.pathname === '/mia' ||
46	    location.pathname === '/logistica' ||
47	    location.pathname === '/logistica/control-tower' ||
48	    location.pathname === '/requisicao' ||
49	    location.pathname === '/requisicao-conclusao' ||
50	    location.pathname === '/atendimento-virtual' ||
51	    location.pathname === '/noaa-supervisor' ||
52	    location.pathname === '/funcionarios' ||
53	    location.pathname.startsWith('/funcionarios/');
54	
55	  return (
56	    <SidebarProvider defaultOpen={!isMobile}>
57	      <StoreChangeNotification />
58	      <div className="h-screen overflow-hidden flex w-full bg-background">
59	        <AppSidebar />
60	        <div className="flex-1 flex flex-col min-w-0 min-h-0 h-full">
61	          <main
62	            className={cn(
63	              'flex-1 min-h-0 overflow-y-auto overflow-x-hidden max-w-full flex flex-col',
64	              (!isMobile || !isDashboard) && 'pb-[env(safe-area-inset-bottom)]',
65	              isFullBleedPage ? 'p-0' : 'p-3 sm:p-4 md:p-6',
66	            )}
67	          >
68	            {children}
69	          </main>
70	        </div>
71	      </div>
72	    </SidebarProvider>
73	  );
74	}
75	
76	/**
77	 * DashboardLayout — wrapper público. MiaProvider foi MOVIDO pro App.tsx
78	 * (acima de Routes) pra persistir state entre navegações — antes ele
79	 * re-montava em cada route change, fazendo chat sumir + tab resetar
80	 * quando MIA usava do_navigate.
81	 */
82	export function DashboardLayout({ children }: DashboardLayoutProps) {
83	  return <DashboardLayoutInner>{children}</DashboardLayoutInner>;
84	}
